      <!-- 박스 2: 편지지 배경 패턴 (4종: 무지, 줄노트, 모눈 그리드, 도트 그리드) -->
      <div style="background:#ffffff;border:1px solid var(--line);border-radius:10px;padding:8px 10px;margin-bottom:8px">
        <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:6px">
          <span style="font-size:11.5px;font-weight:700;color:var(--ink-title)">📐 편지지 배경 패턴</span>
          <span style="font-size:9.5px;color:var(--ink-mut)">무지 · 줄노트 · 모눈 · 도트</span>
        </div>
        <div class="item-card-grid" style="grid-template-columns:repeat(4,1fr);gap:4px">
          ${ie.map(e=>`
            <button type="button" class="grid-item-card ${O.paperPattern===e.id?`on`:``}" data-a="set-paper-pattern" data-v="${e.id}" style="min-height:42px;padding:3px 2px;background:#ffffff;border:1.5px solid ${O.paperPattern===e.id?`var(--accent)`:`var(--line)`}">
              <span class="chk-badge">✓</span>
              <span style="font-size:15px">${e.icon}</span>
              <span class="card-label" style="font-size:9px">${e.name}</span>
            </button>
          `).join(``)}
        </div>
      </div>

